<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('forms.view');$pageTitle='Formularios de captación';$rows=db()->query("SELECT lf.*,lc.name campaign_name,(SELECT COUNT(*) FROM lead_submissions ls WHERE ls.form_id=lf.id) submissions FROM lead_forms lf LEFT JOIN lead_campaigns lc ON lc.id=lf.campaign_id ORDER BY lf.created_at DESC")->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2>Creador de formularios</h2><span class="table-sub">Crea formularios públicos sin escribir código y convierte visitantes en leads.</span></div><?php if(has_permission('forms.manage')):?><a class="btn btn-primary" href="lead_form_builder.php">+ CREAR FORMULARIO</a><?php endif;?></div><div class="table-wrap"><?php if(!$rows):?><div class="empty">No hay formularios creados.</div><?php else:?><table class="data-table"><thead><tr><th>Formulario</th><th>Campaña</th><th>Idioma</th><th>Respuestas</th><th>Estado</th><th>Enlace público</th><th></th></tr></thead><tbody><?php foreach($rows as$r):$url=app_url('lead_form_public.php?token='.$r['public_token']);?><tr><td><strong><?=e($r['name'])?></strong><span class="table-sub"><?=e($r['title'])?></span></td><td><?=e($r['campaign_name']?:'Sin campaña')?></td><td><?=e(language_label($r['language']))?></td><td><a href="lead_submissions.php?form_id=<?=(int)$r['id']?>"><strong><?=(int)$r['submissions']?></strong></a></td><td><span class="badge badge-<?=$r['is_active']?'green':'gray'?>"><?=$r['is_active']?'Activo':'Inactivo'?></span></td><td><button type="button" class="btn btn-light btn-small" data-copy="<?=e($url)?>">Copiar enlace</button></td><td><div class="actions"><a class="btn btn-light btn-small" href="lead_form_public.php?token=<?=e($r['public_token'])?>" target="_blank">Vista pública</a><?php if(has_permission('forms.manage')):?><a class="btn btn-light btn-small" href="lead_form_builder.php?id=<?=(int)$r['id']?>">Editar</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section><script>document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copiado'}));</script><?php require __DIR__.'/includes/footer.php';?>
